CSS+=EXTRA_CSS

def shell(title,body,script=''):
    return '<!doctype html><!-- Generated by scripts/build_report.py; edit the source data and rebuild. --><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>'+esc(title)+'</title><style>'+CSS+'</style></head><body><div class="wrap"><header class="topbar"><a class="brand" href="index.html">LYN ALDEN / RESEARCH AUDIT</a><span class="context">Research audit · As of November 7, 2026</span><button class="theme-toggle" id="theme" aria-label="Toggle light or dark theme">Light / dark</button></header>'+body+'<footer>Independent analysis · Original member articles and charts remain outside this repository · Georgia typography and restrained blue accents follow the original Lyn Alden site.<br>This is a retrospective research audit. Verdict counts are claim occurrences, not independent forecasts or a portfolio track record.</footer></div><script>try{if(localStorage.getItem("lyn-theme")==="dark")document.body.classList.add("dark")}catch(e){}document.getElementById("theme").onclick=()=>{document.body.classList.toggle("dark");try{localStorage.setItem("lyn-theme",document.body.classList.contains("dark")?"dark":"light")}catch(e){}};const lm=location.pathname.match(/^\/artifact\/([^/]+)\//);if(lm&&location.search){document.querySelectorAll("a").forEach(a=>{const h=a.getAttribute("href")||"";if(/^(index|article-[0-9]+)\.html(?:#.*)?$/.test(h)){const u=new URL(h,location.href);u.search=location.search;a.href=u.pathname+u.search+u.hash}})};</script>'+script+'</body></html>'

def badge(v,n=None):
    return f'<span class="badge {esc(v)}">{esc(labels.get(v,v))}{" · "+str(n) if n is not None else ""}</span>'

def source_links(ids):
    return '<div class="source-list">'+''.join(f'<a href="article-{esc(i)}.html">Report {esc(i)}</a>' for i in ids)+'</div>'

def finding_html(finding):
    """Present stored return calculations as readable evidence, retaining raw JSON."""
    try:
        data=json.loads(finding)
    except (ValueError,TypeError):
        return esc(finding)
    if not isinstance(data,dict) or not isinstance(data.get('instruments'),dict):
        return esc(finding)
    def number(value,suffix=''):
        return f'{value:,.2f}{suffix}' if isinstance(value,(int,float)) else 'Not available'
    rows=''
    for symbol,values in data['instruments'].items():
        if not isinstance(values,dict): continue
        rows+='<tr><td>'+esc(symbol)+'</td><td>'+number(values.get('entry_adjusted_close'))+'</td><td>'+number(values.get('exit_adjusted_close'))+'</td><td>'+number(values.get('cumulative_return_pct'),'%')+'</td><td>'+number(values.get('annualized_return_pct'),'%')+'</td></tr>'
    window='<p class="small">Observed window: <b>'+esc(data.get('entry','unspecified'))+'</b> to <b>'+esc(data.get('exit','unspecified'))+'</b>. Requested endpoint: '+esc(data.get('requested_endpoint','unspecified'))+'.</p>'
    table='<div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Entry adjusted price</th><th>Exit adjusted price</th><th>Return</th><th>Annualized</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
    warning=''
    if data.get('endpoint_covered') is False:
        warning='<p class="small"><b>Incomplete endpoint coverage:</b> the last observation is '+esc(data.get('endpoint_gap_days','unknown'))+' days before the requested endpoint.</p>'
    return window+table+warning+'<p class="small muted">'+esc(data.get('method','Vendor-adjusted price proxy; verify distributions and corporate actions.'))+'</p>'

def claim_html(c):
    evidence=''.join('<li><a target="_blank" rel="noopener" href="'+esc(e['url'])+'">'+esc(e.get('title') or e.get('publisher') or e['url'])+'</a>'+(' · '+esc(e['date']) if e.get('date') else '')+(' <span class="muted">[not independently opened]</span>' if not e.get('verified') else '')+'<br>'+finding_html(e.get('finding',''))+'</li>' for e in c.get('evidence',[]))
    proof=c.get('proof') or {}
    assumptions=proof.get('assumptions',[])
    if isinstance(assumptions,str): assumptions=[assumptions]
    deductive=''
    if c.get('evidence_basis')=='deductive' and isinstance(proof,dict):
        deductive='<div class="evidence"><b>Deductive reasoning, not an empirical outcome test</b><p>'+esc(proof.get('derivation',''))+'</p><p class="small">Assumptions: '+esc('; '.join(assumptions))+'</p></div>'
    evidence_empty = 'This explanation is assessed through its stated derivation, not an observed forecast result.' if deductive else 'No independent outcome source is recorded. This claim cannot support a resolved empirical accuracy score.'
    spec=''.join('<div><b>'+name+'</b>'+esc(value or 'Not specified')+'</div>' for name,value in [('Horizon',c.get('horizon')),('Conditions',c.get('conditions')),('Author modality',c.get('modality'))])
    dimensions=''.join('<p><b>'+name+':</b> '+esc(c.get(key) or 'Not separately established')+'</p>' for name,key in [('Direction','direction_assessment'),('Timing','timing_assessment'),('Mechanism','mechanism_assessment')])
    return f'''<section class="claim-card" id="{esc(c['id'])}"><div class="claim-top"><div><div class="meta">{esc(c['id'])} · {esc(c.get('kind','').replace('_',' '))} · source blocks {esc(', '.join(map(str,c.get('source_blocks',[]))))}</div><h3>{esc(c['claim'])}</h3></div>{badge(c['verdict'])}</div><div class="spec">{spec}</div>{deductive}<p>{esc(c.get('reason',''))}</p>{('<p class="small"><b>Next test:</b> '+esc(c['next_check'])+'</p>') if c.get('next_check') else ''}<details><summary>Direction, timing, mechanism and confidence</summary>{dimensions}<p>Reviewer confidence: {esc(c.get('confidence','unspecified'))}. Thesis family: {esc(c.get('family','unclassified'))}.</p></details><div class="evidence"><b>Independent evidence</b>{'<ul>'+evidence+'</ul>' if evidence else '<p class="muted">'+evidence_empty+'</p>'}</div></section>'''

article_index=[]
all_claims=[]
for i,s in enumerate(sources):
    aid=s['id']; r=reviews.get(aid)
    counts=Counter(c['verdict'] for c in r.get('claims',[])) if r else Counter()
    entry={'id':aid,'title':s['title'],'date':s['publication_date'],'year':s['publication_date'][:4],'source_url':s['url'],'reviewed':bool(r),'summary':r.get('summary','Review in progress.') if r else 'Review in progress.','counts':dict(counts),'claims':len(r.get('claims',[])) if r else 0}
    article_index.append(entry)
    if r:
        all_claims.extend({**c,'article_id':aid,'article_title':s['title'],'date':s['publication_date']} for c in r.get('claims',[]))
    back='<a href="index.html">← Return to research library</a>'
    prev=f'<a href="article-{sources[i-1]["id"]}.html">← {esc(sources[i-1]["title"])}</a>' if i else '<span></span>'
    next_=f'<a href="article-{sources[i+1]["id"]}.html">{esc(sources[i+1]["title"])} →</a>' if i+1<len(sources) else '<span></span>'
    body=f'<div class="article-header"><div class="eyebrow">Report {aid} · {s["publication_date"]}</div><h1>{esc(s["title"])}</h1><p>{esc(entry["summary"])}</p><div class="meta"><a href="{esc(s["url"])}" target="_blank" rel="noopener">Open original members article ↗</a> · Retrieved November 7, 2026</div></div><main class="article-body">'
    if r:
        body+='<div class="badges">'+''.join(badge(v,n) for v,n in counts.items())+'</div><div class="callout">'+esc(r.get('assessment',''))+'</div>'
        body+='<div class="note"><b>Coverage.</b> '+esc(r.get('coverage_note',''))+'</div><h2>Claim-by-claim assessment</h2>'
        body+=''.join(claim_html(c) for c in r.get('claims',[]))
        body+='<h2>Analytical tools and framework</h2><ul>'+''.join('<li><b>'+esc(t['name'])+'</b>: '+esc(t.get('use',''))+(' <span class="muted small">(image not visually inspected)</span>' if not t.get('image_inspected') else '')+'</li>' for t in r.get('tools_charts',[]))+'</ul>'
        body+=''.join('<p>'+esc(l)+'</p>' for l in r.get('framework_lessons',[]))
        if r.get('verification_limitations'): body+='<details><summary>Verification limitations</summary><ul>'+''.join('<li>'+esc(l)+'</li>' for l in r['verification_limitations'])+'</ul></details>'
    else:
        body+='<div class="note">This source has been captured. Its material-claim review and outcome verification are not yet complete. No verdict has been assigned.</div>'
    body+=f'<div class="article-nav">{prev}{next_}</div><p class="small">{back}</p></main>'
    (OUT/f'article-{aid}.html').write_text(shell(s['title']+' | Lyn Alden audit',body))

groups=[
 ('Business cycle','heatmap|heat map|PMI|GDPNow|GDP Now|ISM|jobless|unemployment|payroll|consumer sentiment|leading economic|retail sales','Growth rates and breadth: distinguish a slowdown from contraction.'),
 ('Domestic liquidity','domestic liquidity|\\bTGA\\b|reverse repo|fed balance sheet|bank cash|SOFR|reserves|treasury general','Separate Fed assets, Treasury cash, money-fund balances and bank funding.'),
 ('Valuation and cash flow','FAST.?Graph|Fast Graph|CAPE|Shiller|P/E|PE Ratio','Compare price with earnings, cash generation and historical multiples.'),
 ('Global money and currencies','global M2|dollar index|\\bDXY\\b|USDJPY|china credit impulse','Connect dollar funding, local liquidity, currencies and international assets.'),
 ('Bitcoin ownership and valuation','MVRV|HODL|RHODL|realized cap|realized price','Use ownership and cost-basis proxies alongside liquidity and adoption.'),
 ('Energy and commodity supply','WTI|oil production|strategic petroleum|rig count|natural gas|crude|brent|uranium','Track inventories, production, capacity and long investment cycles.'),
 ('Gold and real yields','gold vs real|real rates|real yields|TIPS','Distinguish inflation compensation, real interest rates and monetary hedges.')]
tool_rows=[]
for name,pattern,use in groups:
    matches=[s for s in sources if any(re.search(pattern,im['alt'],re.I) for im in s['images'])]
    alt=Counter(im['alt'] for s in matches for im in s['images'] if re.search(pattern,im['alt'],re.I))
    tool_rows.append({'name':name,'articles':len(matches),'use':use,'labels':[x for x,n in alt.most_common(5)],'examples':[s['id'] for s in (matches[:1]+matches[-2:])]})
# Chart inventory is derived from the published source-label metadata.

counts=Counter(c['verdict'] for c in all_claims)
resolved=sum(counts.get(k,0) for k in ['right','wrong'])
body=f'''<section class="hero"><div class="eyebrow">The members archive · 2019-2026</div><h1>Lyn Alden, examined<br>one claim at a time.</h1><p>A research scorecard, an article-by-article reading library, and a practical guide to the questions behind her investment framework.</p></section><section class="stats" aria-label="Audit coverage"><div class="stat"><strong>{len(sources)}</strong>source reports captured</div><div class="stat"><strong>{len(reviews)} / {len(sources)}</strong>article reviews available</div><div class="stat"><strong>{len(all_claims):,}</strong>material claim occurrences</div><div class="stat"><strong>{resolved:,}</strong>right / wrong assessments</div></section>'''
if len(reviews)<len(sources): body+='<div class="note"><b>Work in progress.</b> Source capture is complete; reading, verification and synthesis continue. Unreviewed articles are explicitly marked. There is no complete-archive accuracy score yet.</div>'
body+='<div class="note">A forecast can get the direction right while missing the timing or mechanism. This audit keeps those separate. Repeated claims, factual descriptions and investment returns are not pooled into one success rate.</div>'
body+='''<nav aria-label="Research sections" role="tablist"><button data-panel="library" role="tab" aria-selected="true">Article reviews</button><button data-panel="claims" role="tab" aria-selected="false">Claim scorecard</button><button data-panel="framework" role="tab" aria-selected="false">How Lyn thinks</button><button data-panel="tools" role="tab" aria-selected="false">Tools & charts</button><button data-panel="method" role="tab" aria-selected="false">Method & coverage</button></nav><main><section class="panel" id="library"><h2>The article library</h2><div class="filters"><input id="article-search" type="search" placeholder="Search titles, summaries or claim language" aria-label="Search article reviews"><select id="year" aria-label="Publication year"><option value="">All years</option>'''+''.join('<option>'+y+'</option>' for y in sorted({s['publication_date'][:4] for s in sources},reverse=True))+'''</select><select id="coverage" aria-label="Review coverage"><option value="">All articles</option><option value="reviewed">Reviewed</option><option value="pending">Pending review</option></select></div><div class="result-count" id="article-count"></div><div class="grid" id="articles"></div></section><section class="panel" id="claims" hidden><h2>The claim scorecard</h2><p class="measure muted">Filter material claims by outcome and type. Counts describe claim occurrences. Shared thesis families can recur across reports and are not independent observations.</p><div class="badges">'''+''.join(badge(v,counts.get(v,0)) for v in labels)+'''</div><div class="filters" style="margin-top:25px"><input id="claim-search" type="search" placeholder="Search claims, assets, explanations or evidence" aria-label="Search claims"><select id="verdict" aria-label="Claim verdict"><option value="">All verdicts</option>'''+''.join(f'<option value="{v}">{l}</option>' for v,l in labels.items())+'''</select><select id="kind" aria-label="Claim type"><option value="">All claim types</option><option value="forecast">Forecast</option><option value="explanation">Explanation</option><option value="investment_thesis">Investment thesis</option><option value="empirical">Empirical assertion</option></select></div><div class="result-count" id="claim-count"></div><div id="claim-results"></div><button id="more" hidden>Show 50 more claims</button></section><section class="panel" id="framework" hidden><h2>How would Lyn think about this?</h2>'''
if synthesis:
    body+=framework_diagram()
    body+='<div class="prose">'+''.join('<p>'+esc(x)+'</p>' for x in synthesis.get('introduction',[]))+'</div>'
    body+=views_section(synthesis)
    body+='<h2 class="section-space">The questions to ask, in order</h2>'
    for i,step in enumerate(synthesis.get('steps',[]),1): body+='<div class="framework-step"><div class="number">'+str(i).zfill(2)+'</div><div><h3>'+esc(step['question'])+'</h3><p>'+esc(step['explanation'])+'</p>'+source_links(step.get('article_ids',[]))+'</div></div>'
    body+='<h2 style="margin-top:40px">Where the framework helps, and where it needs resistance</h2><div class="grid">'+''.join('<article class="card"><h3>'+esc(x['title'])+'</h3><p>'+esc(x['text'])+'</p>'+source_links(x.get('article_ids',[]))+'</article>' for x in synthesis.get('takeaways',[]))+'</div>'
    body+=examples_section(synthesis)
else: body+='<div class="note">The source-based framework synthesis is being assembled alongside article verification. It will distinguish the author’s recurring method from the reviewer’s own inferences.</div>'
body+='</section><section class="panel" id="tools" hidden><h2>The recurring analytical toolkit</h2><p class="measure muted">This inventory scans image labels in every report. Counts are the number of reports with a matching label, not the number of charts or a measure of predictive usefulness. Variations in labels mean some uses will be missed. The taxonomy below groups the recurring analytical roles; the representative inspections explain how to read the charts and where inference can fail.</p><div class="table-wrap"><table><thead><tr><th>Tool family</th><th>Reports</th><th>Analytical role</th><th>Observed labels & examples</th></tr></thead><tbody>'
for t in tool_rows: body+='<tr><td><b>'+esc(t['name'])+'</b></td><td>'+str(t['articles'])+' / 200</td><td>'+esc(t['use'])+'</td><td>'+esc(', '.join(t['labels']))+source_links(t['examples'])+'</td></tr>'
body+='</tbody></table></div>'+charts_section(json.loads((ROOT/'representative-charts.json').read_text()),OUT)+glossary_section()+'</section><section class="panel" id="method" hidden><div class="prose"><h2>What this audit measures</h2><p>'+esc(method['scope'])+'</p><h3>Materiality</h3><p>'+esc(method['materiality'])+'</p><h3>Source versions</h3><p>'+esc(method['source_vintage'])+'</p><h3>Verdicts</h3><ul>'+''.join('<li><b>'+esc(labels[k])+':</b> '+esc(v)+'</li>' for k,v in method['verdicts'].items())+'</ul><h3>Evidence and scoring rules</h3><ol>'+''.join('<li>'+esc(x)+'</li>' for x in method['rules'])+'</ol><h3>Independent methodology review</h3><p>'+esc(method['external_review'])+'</p></div></section></main>'

if synthesis:
    body=body.replace('<nav aria-label="Research sections" role="tablist">','<nav aria-label="Research sections" role="tablist"><button data-panel="summary" role="tab" aria-selected="true">Overall summary</button>',1)
    body=body.replace('data-panel="library" role="tab" aria-selected="true"','data-panel="library" role="tab" aria-selected="false"',1)
    body=body.replace('<main><section class="panel" id="library">','<main>'+summary_section(synthesis,all_claims,reviews,labels)+'<section class="panel" id="library" hidden>',1)

if method.get('peer_review'):
    body=body.replace('<h3>Independent methodology review</h3>','<h3>Review quality check</h3><p>'+esc(method['peer_review'])+'</p><h3>Independent methodology review</h3>',1)

DATA={'articles':article_index,'claims':all_claims,'labels':labels}
JS='''<script id="audit-data" type="application/json">'''+safejson(DATA)+'''</script><script>
const D=JSON.parse(document.getElementById('audit-data').textContent),$=id=>document.getElementById(id);const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const localHref=h=>location.pathname.startsWith('/artifact/')&&location.search?h.split('#')[0]+location.search+(h.includes('#')?'#'+h.split('#')[1]:''):h;const badge=(v,n)=>`<span class="badge ${E(v)}">${E(D.labels[v]||v)}${n===undefined?'':' · '+n}</span>`;let limit=50;
function openPanel(name){document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.panel===name)));history.replaceState(null,'','#'+name)}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));if(['summary','library','claims','framework','tools','method'].includes(location.hash.slice(1)))openPanel(location.hash.slice(1));
const articleClaims=new Map;for(const c of D.claims){articleClaims.set(c.article_id,(articleClaims.get(c.article_id)||'')+' '+c.claim+' '+c.reason)}
function renderArticles(){const q=$('article-search').value.toLowerCase(),y=$('year').value,c=$('coverage').value;const items=D.articles.filter(a=>(!y||a.year===y)&&(!c||(c==='reviewed'?a.reviewed:!a.reviewed))&&(!q||[a.title,a.summary,articleClaims.get(a.id)||''].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date));$('article-count').textContent=items.length+(items.length===1?' article':' articles');$('articles').innerHTML=items.map(a=>`<article class="card"><div class="meta">${E(a.date)} · REPORT ${E(a.id)}</div><h3><a href="${localHref(`article-${E(a.id)}.html`)}">${E(a.title)}</a></h3><p>${E(a.summary)}</p><div class="badges">${a.reviewed?Object.entries(a.counts).map(([v,n])=>badge(v,n)).join(''):'<span class="badge evidence_needed">Review pending</span>'}</div><p class="small" style="margin:20px 0 0"><a href="${localHref(`article-${E(a.id)}.html`)}">${a.reviewed?'Read review · '+a.claims+' claims':'Source & review status'} →</a></p></article>`).join('')||'<div class="empty">No articles match these filters.</div>'};['article-search','year','coverage'].forEach(id=>$(id).addEventListener('input',renderArticles));renderArticles();
function renderClaims(reset=true){if(reset)limit=50;const q=$('claim-search').value.toLowerCase(),v=$('verdict').value,k=$('kind').value;const items=D.claims.filter(c=>(!v||c.verdict===v)&&(!k||c.kind===k)&&(!q||[c.claim,c.reason,c.asset_or_variable,c.family,c.article_title,...(c.evidence||[]).map(e=>e.finding)].join(' ').toLowerCase().includes(q)));$('claim-count').textContent=items.length+(items.length===1?' matching claim occurrence · showing ':' matching claim occurrences · showing ')+Math.min(limit,items.length);$('claim-results').innerHTML=items.slice(0,limit).map(c=>`<article class="claim-card"><div class="claim-top"><div><div class="meta">${E(c.date)} · ${E(c.kind.replaceAll('_',' '))} · ${E(c.id)}</div><h3><a href="${localHref(`article-${E(c.article_id)}.html#${E(c.id)}`)}">${E(c.claim)}</a></h3></div>${badge(c.verdict)}</div><p>${E(c.reason)}</p><div class="meta">${E(c.article_title)} · ${(c.evidence||[]).filter(e=>e.verified).length} verified evidence ${(c.evidence||[]).filter(e=>e.verified).length===1?'link':'links'}</div></article>`).join('')||'<div class="empty">No claims match these filters.</div>';$('more').hidden=limit>=items.length};['claim-search','verdict','kind'].forEach(id=>$(id).addEventListener('input',()=>renderClaims()));$('more').onclick=()=>{limit+=50;renderClaims(false)};renderClaims();
</script>'''
(OUT/'index.html').write_text(shell('Lyn Alden | Research scorecard',body,JS))
(OUT/'audit-data.json').write_text(json.dumps(DATA,indent=2,ensure_ascii=False))
print(f'Built {len(sources)} article pages; {len(reviews)} reviewed; {len(all_claims)} claims.')
